import React, { useState } from 'react';
import './LoginPage.css';

const LoginPage = ({ onLogin }) => {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    licenseNumber: '',
    vehicleNumber: '',
    carModel: '',
    licensePhoto: null,
    carPhoto: null
  });

  const [previewLicense, setPreviewLicense] = useState(null);
  const [previewCar, setPreviewCar] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleFileChange = (e, type) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (type === 'license') {
          setPreviewLicense(reader.result);
          setFormData(prev => ({ ...prev, licensePhoto: file }));
        } else {
          setPreviewCar(reader.result);
          setFormData(prev => ({ ...prev, carPhoto: file }));
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Validate PB11 in vehicle number
    if (!formData.vehicleNumber.toUpperCase().includes('PB11')) {
      alert('Vehicle number must include PB11 tag for Patiala registration');
      return;
    }
    
    // Store driver data and navigate to feed
    localStorage.setItem('driverData', JSON.stringify(formData));
    onLogin();
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="login-header">
          <div className="logo-section">
            <div className="logo-icon">🚗</div>
            <h1>Driver Community</h1>
            <p className="location-badge">📍 Patiala (PB11)</p>
          </div>
          <h2>Join Our Community</h2>
          <p className="subtitle">Connect with fellow drivers, share rides & stay updated</p>
        </div>

        <form className="login-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="name">Full Name</label>
            <input
              type="text"
              id="name"
              name="name"
              value={formData.name}
              onChange={handleChange}
              placeholder="Enter your full name"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="phone">Phone Number</label>
            <input
              type="tel"
              id="phone"
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              placeholder="+91 XXXXX XXXXX"
              pattern="[0-9]{10}"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="licenseNumber">Driving License Number</label>
            <input
              type="text"
              id="licenseNumber"
              name="licenseNumber"
              value={formData.licenseNumber}
              onChange={handleChange}
              placeholder="DL-XXXXXXXXXX"
              required
            />
          </div>

          <div className="form-group file-upload-group">
            <label>Upload Driving License (Optional)</label>
            <div className="file-upload-box">
              <input
                type="file"
                id="licensePhoto"
                accept="image/*"
                onChange={(e) => handleFileChange(e, 'license')}
              />
              <label htmlFor="licensePhoto" className="file-upload-label">
                {previewLicense ? (
                  <img src={previewLicense} alt="License preview" className="preview-image" />
                ) : (
                  <>
                    <span className="upload-icon">📄</span>
                    <span>Click to upload license photo</span>
                  </>
                )}
              </label>
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="vehicleNumber">Vehicle Number</label>
            <input
              type="text"
              id="vehicleNumber"
              name="vehicleNumber"
              value={formData.vehicleNumber}
              onChange={handleChange}
              placeholder="PB11-XX-XXXX (Must include PB11)"
              required
            />
            <small className="form-hint">⚠️ Must include PB11 for Patiala registration</small>
          </div>

          <div className="form-group">
            <label htmlFor="carModel">Car Model</label>
            <input
              type="text"
              id="carModel"
              name="carModel"
              value={formData.carModel}
              onChange={handleChange}
              placeholder="e.g., Maruti Swift, Hyundai i20"
              required
            />
          </div>

          <div className="form-group file-upload-group">
            <label>Upload Car Photo</label>
            <div className="file-upload-box">
              <input
                type="file"
                id="carPhoto"
                accept="image/*"
                onChange={(e) => handleFileChange(e, 'car')}
                required
              />
              <label htmlFor="carPhoto" className="file-upload-label">
                {previewCar ? (
                  <img src={previewCar} alt="Car preview" className="preview-image" />
                ) : (
                  <>
                    <span className="upload-icon">🚙</span>
                    <span>Click to upload car photo</span>
                  </>
                )}
              </label>
            </div>
          </div>

          <button type="submit" className="submit-btn">
            <span>Join Patiala Community</span>
            <span className="btn-arrow">→</span>
          </button>

          <div className="community-badge-info">
            <span className="badge-icon">✓</span>
            <span>You'll automatically get the Patiala Community Badge</span>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginPage;
